Here is the generated code to evaluate:

<!-- @FIGURE_UI_BEGIN -->
<label>
  Angle θ
  <input type="range" id="coilAngle" min="0" max="360" step="1" value="45">
</label>
<button id="playRotation">Play Rotation</button>
<label>
  View Mode
  <select id="displayMode">
    <option value="3D Coil">3D Coil</option>
    <option value="Split: Coil & Graphs">Split: Coil & Graphs</option>
  </select>
</label>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
const coilAngleInput = document.getElementById('coilAngle');
const playRotationBtn = document.getElementById('playRotation');
const displayModeSelect = document.getElementById('displayMode');

// ─── 2D GRAPH PANEL SETUP ────────────────────────────────────────────────────
const graphPanel = document.createElement('div');
graphPanel.id = 'graph-panel';
graphPanel.style.position = 'absolute';
graphPanel.style.right = '0';
graphPanel.style.top = '0';
graphPanel.style.width = '50%';
graphPanel.style.height = '100%';
graphPanel.style.background = '#fff';
graphPanel.style.borderLeft = '1px solid #ccc';
graphPanel.style.boxSizing = 'border-box';
graphPanel.style.padding = '15px';
graphPanel.style.display = 'none';
graphPanel.style.zIndex = '5';
_stage.appendChild(graphPanel);

const svgNS = "http://www.w3.org/2000/svg";
const svg = document.createElementNS(svgNS, "svg");
svg.setAttribute("width", "100%");
svg.setAttribute("height", "100%");
svg.style.display = "block";
graphPanel.appendChild(svg);

function createSVGPath(color, strokeWidth = "2") {
    const path = document.createElementNS(svgNS, "path");
    path.setAttribute("fill", "none");
    path.setAttribute("stroke", color);
    path.setAttribute("stroke-width", strokeWidth);
    return path;
}
function createSVGText(text, color, bold = false, size = "13px") {
    const t = document.createElementNS(svgNS, "text");
    t.textContent = text;
    t.setAttribute("fill", color);
    t.setAttribute("font-family", "sans-serif");
    t.setAttribute("font-size", size);
    if (bold) t.setAttribute("font-weight", "bold");
    return t;
}

const fluxPath = createSVGPath("#0077cc");
const emfPath = createSVGPath("#e68a00");
svg.appendChild(fluxPath);
svg.appendChild(emfPath);

const axisLineY = createSVGPath("#000", "1");
const axisLineX1 = createSVGPath("#000", "1");
const axisLineX2 = createSVGPath("#000", "1");
svg.appendChild(axisLineY);
svg.appendChild(axisLineX1);
svg.appendChild(axisLineX2);

const markerLine = createSVGPath("#ff0000", "1.5");
markerLine.setAttribute("stroke-dasharray", "4,4");
svg.appendChild(markerLine);

const lblFlux = createSVGText("Magnetic Flux Φ = cos(θ)", "#0077cc", true);
const lblEMF = createSVGText("Induced EMF ε = sin(θ)", "#e68a00", true);
svg.appendChild(lblFlux);
svg.appendChild(lblEMF);

const labelsX = [];
const angles = [0, 90, 180, 270, 360];
for (let j = 0; j < 5; j++) {
    const t = createSVGText(angles[j] + "°", "#888", false, "10px");
    svg.appendChild(t);
    labelsX.push(t);
}

function updateGraph(theta) {
    if (graphPanel.style.display === 'none') return;
    const rect = svg.getBoundingClientRect();
    if (rect.width === 0) return;

    const w = rect.width;
    const h = rect.height;
    const padX = 35;
    const padY = 25;
    const h1 = (h - padY * 2) / 2;

    const xStart = padX;
    const xEnd = w - 15;
    const graphW = xEnd - xStart;

    axisLineY.setAttribute("d", `M ${xStart},${padY - 10} L ${xStart},${h - padY + 10}`);

    const mid1 = padY + h1 / 2;
    const mid2 = padY + h1 + h1 / 2;

    axisLineX1.setAttribute("d", `M ${xStart},${mid1} L ${xEnd},${mid1}`);
    axisLineX2.setAttribute("d", `M ${xStart},${mid2} L ${xEnd},${mid2}`);

    lblFlux.setAttribute("x", xStart + 10);
    lblFlux.setAttribute("y", padY + 5);
    lblEMF.setAttribute("x", xStart + 10);
    lblEMF.setAttribute("y", padY + h1 + 5);

    for (let j = 0; j < 5; j++) {
        const lx = xStart + (angles[j] / 360) * graphW;
        labelsX[j].setAttribute("x", lx - 8);
        labelsX[j].setAttribute("y", mid2 + 15);
    }

    let dFlux = "", dEMF = "";
    const points = 80;
    const amp = h1 / 2 - 15;
    for(let i = 0; i <= points; i++) {
        const th_iter = (i / points) * Math.PI * 2;
        const x = xStart + (i / points) * graphW;

        const yF = mid1 - Math.cos(th_iter) * amp;
        dFlux += (i === 0 ? "M " : "L ") + `${x},${yF}`;

        const yE = mid2 - Math.sin(th_iter) * amp;
        dEMF += (i === 0 ? "M " : "L ") + `${x},${yE}`;
    }
    fluxPath.setAttribute("d", dFlux);
    emfPath.setAttribute("d", dEMF);

    const curX = xStart + (theta / 360) * graphW;
    markerLine.setAttribute("d", `M ${curX},${padY - 10} L ${curX},${h - padY + 10}`);
}

new ResizeObserver(() => {
    if (graphPanel.style.display !== 'none') {
        updateGraph(Number(coilAngleInput.value));
    }
}).observe(graphPanel);

// ─── 3D SCENE SETUP ──────────────────────────────────────────────────────────

// Axes materials
const matSolid = new THREE.LineBasicMaterial({ color: 0x000000 });
const matDash = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.2, gapSize: 0.1 });

// Y axis (labeled z in diagram)
const yAxisTop = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 2.5, 0), new THREE.Vector3(0, 4.8, 0)
]), matSolid);
const yAxisBot = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, -2.5, 0), new THREE.Vector3(0, -4.5, 0)
]), matSolid);
const yAxisMid = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, -2.5, 0), new THREE.Vector3(0, 2.5, 0)
]), matDash);
yAxisMid.computeLineDistances();
scene.add(yAxisTop, yAxisBot, yAxisMid);

const yArrow = new THREE.ArrowHelper(new THREE.Vector3(0,1,0), new THREE.Vector3(0,4.8,0), 0.001, 0x000000, 0.3, 0.15);
scene.add(yArrow);

// Z axis (labeled x in diagram, diagonal in projection)
const zFront = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, 0), new THREE.Vector3(0, 0, 4.5)
]), matSolid);
const zBack = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, -4.5), new THREE.Vector3(0, 0, 0)
]), matDash);
zBack.computeLineDistances();
scene.add(zFront, zBack);

const zArrow = new THREE.ArrowHelper(new THREE.Vector3(0,0,1), new THREE.Vector3(0,0,4.5), 0.001, 0x000000, 0.3, 0.15);
scene.add(zArrow);

// Rotation indicator arrow
const rotArcRadius = 1.2;
const rotArcPoints = [];
for (let i = 0; i <= 30; i++) {
    const a = -Math.PI * 0.2 + (i / 30) * Math.PI * 1.4;
    rotArcPoints.push(new THREE.Vector3(Math.cos(a) * rotArcRadius, 4.2, Math.sin(a) * rotArcRadius));
}
const rotArc = new THREE.Line(new THREE.BufferGeometry().setFromPoints(rotArcPoints), matSolid);
scene.add(rotArc);

const rotArcEnd = -Math.PI * 0.2 + Math.PI * 1.4;
const rotArcDir = new THREE.Vector3(-Math.sin(rotArcEnd), 0, Math.cos(rotArcEnd)).normalize();
const rotArcHead = new THREE.ArrowHelper(rotArcDir, rotArcPoints[rotArcPoints.length - 1], 0.001, 0x000000, 0.3, 0.15);
scene.add(rotArcHead);

// Coil Geometry
const coilGroup = new THREE.Group();
scene.add(coilGroup);

const coilMat = new THREE.LineBasicMaterial({ color: 0xb3b3b3, linewidth: 2 });
for (let i = 0; i < 4; i++) {
    const dw = i * 0.08;
    const dh = i * 0.08;
    const pts = [
        new THREE.Vector3(0, 2.5 + dh, 1.75 + dw),
        new THREE.Vector3(0, 2.5 + dh, -1.75 - dw),
        new THREE.Vector3(0, -2.5 - dh, -1.75 - dw),
        new THREE.Vector3(0, -2.5 - dh, 1.75 + dw),
        new THREE.Vector3(0, 2.5 + dh, 1.75 + dw)
    ];
    coilGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), coilMat));
}

// Bold Vector Helper
function createBoldArrow(dir, origin, length, color) {
    const group = new THREE.Group();
    const cylLen = length - 0.4;
    const cylGeom = new THREE.CylinderGeometry(0.04, 0.04, cylLen, 8);
    cylGeom.translate(0, cylLen / 2, 0);
    const mat = new THREE.MeshBasicMaterial({ color: color });
    group.add(new THREE.Mesh(cylGeom, mat));

    const coneGeom = new THREE.ConeGeometry(0.12, 0.4, 12);
    coneGeom.translate(0, length - 0.2, 0);
    group.add(new THREE.Mesh(coneGeom, mat));

    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
    group.quaternion.copy(q);
    group.position.copy(origin);
    return group;
}

// Fixed B Field Vector
const bArrow = createBoldArrow(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 4, 0x0077cc);
scene.add(bArrow);

// Rotating Normal Vector
const nArrow = createBoldArrow(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 3, 0xe68a00);
coilGroup.add(nArrow);

// Theta Angle Arc
const thetaArcLine = new THREE.Line(new THREE.BufferGeometry(), matSolid);
scene.add(thetaArcLine);
const thetaArrow = new THREE.ArrowHelper(new THREE.Vector3(), new THREE.Vector3(), 0.001, 0x000000, 0.2, 0.1);
scene.add(thetaArrow);

// Labels
const lbl_z = addLabel('<i>z</i>', new THREE.Vector3(0, 5.1, 0));
const lbl_x = addLabel('<i>x</i>', new THREE.Vector3(0, 0, 5.0));
const lbl_B = addLabel('<b>B</b>', new THREE.Vector3(4.3, 0.2, 0), { color: '#0077cc', fontSize: '15px' });
const lbl_n = addLabel('<b>n̂</b>', new THREE.Vector3(0, 0, 0), { color: '#e68a00', fontSize: '15px' });
const lbl_theta = addLabel('θ', new THREE.Vector3(0, 0, 0));

// Interactive tooltips
registerInteractive(rotArc, {
    title: "Rotation Direction",
    tooltip: "Direction of coil rotation",
    body: "The coil rotates steadily, causing the area normal to continuously sweep against the constant magnetic field."
});
registerInteractive(bArrow, {
    title: "Magnetic Field (B)",
    tooltip: "Uniform external magnetic field",
    body: "The field is uniform and stationary, passing through the space where the coil rotates."
});
registerInteractive(nArrow, {
    title: "Area Normal (n̂)",
    tooltip: "Perpendicular vector to the coil face",
    body: "This unit vector tracks the orientation of the coil's face. The angle θ between it and the B-field dictates the instantaneous magnetic flux."
});

// ─── STATE & ANIMATION ───────────────────────────────────────────────────────

let isPlaying = false;
const clock = new THREE.Clock();

function updateScene() {
    let th = Number(coilAngleInput.value);
    const rad = th * Math.PI / 180;

    // Rotate coil (n-hat sweeps from +X toward +Z, which is a -Y rotation in right-handed space)
    coilGroup.rotation.y = -rad;
    coilGroup.updateMatrixWorld(true);

    // Position n-hat label at tip
    const tipLocal = new THREE.Vector3(3.3, 0, 0);
    const tipWorld = tipLocal.clone().applyMatrix4(coilGroup.matrixWorld);
    lbl_n.pos.copy(tipWorld);

    // Draw theta arc in world space
    if (rad < 0.03) {
        thetaArcLine.visible = false;
        thetaArrow.visible = false;
        lbl_theta.div.style.display = 'none';
    } else {
        thetaArcLine.visible = true;
        thetaArrow.visible = true;
        lbl_theta.div.style.display = '';

        const arcPts = [];
        const r = 1.3;
        const steps = Math.max(5, Math.floor((rad / Math.PI) * 20));
        for (let i = 0; i <= steps; i++) {
            const a = (i / steps) * rad;
            arcPts.push(new THREE.Vector3(r * Math.cos(a), 0, r * Math.sin(a)));
        }
        thetaArcLine.geometry.setFromPoints(arcPts);

        const lastPt = arcPts[arcPts.length - 1];
        const tang = new THREE.Vector3(-Math.sin(rad), 0, Math.cos(rad)).normalize();
        thetaArrow.position.copy(lastPt);
        thetaArrow.setDirection(tang);

        const halfA = rad / 2;
        lbl_theta.pos.set((r + 0.3) * Math.cos(halfA), 0, (r + 0.3) * Math.sin(halfA));
    }

    if (displayModeSelect.value.startsWith('Split')) {
        updateGraph(th);
    }
}

playRotationBtn.addEventListener('click', () => {
    isPlaying = !isPlaying;
    playRotationBtn.textContent = isPlaying ? 'Stop Rotation' : 'Play Rotation';
    playRotationBtn.classList.toggle('active', isPlaying);
    if (isPlaying) clock.getDelta(); // reset clock
});

coilAngleInput.addEventListener('input', () => {
    if (isPlaying) {
        isPlaying = false;
        playRotationBtn.textContent = 'Play Rotation';
        playRotationBtn.classList.remove('active');
    }
    updateScene();
});

displayModeSelect.addEventListener('change', () => {
    const isSplit = displayModeSelect.value.startsWith('Split');
    if (isSplit) {
        canvas.style.width = '50%';
        graphPanel.style.display = 'block';
    } else {
        canvas.style.width = '100%';
        graphPanel.style.display = 'none';
    }
    window.dispatchEvent(new Event('resize'));
    updateScene();
});

function tickAnimation() {
    requestAnimationFrame(tickAnimation);
    if (isPlaying) {
        let th = Number(coilAngleInput.value);
        th += 60 * clock.getDelta(); // 60 degrees per second
        if (th >= 360) th -= 360;
        coilAngleInput.value = th;
        updateScene();
    }
}
tickAnimation();

setCameraView({ 
    projection: 'orthographic', 
    axisScreenAngles: { x: 30, z: 30 }, 
    heightFraction: 0.65 
});

updateScene();
// @FIGURE_CODE_END

