// @FIGURE_CODE_BEGIN
const coilAngleInput = document.getElementById('coilAngle');
const playRotationBtn = document.getElementById('playRotation');
const showGraphsToggle = document.getElementById('showGraphsToggle');
const graphContainer = document.getElementById('graphContainer');

// ─── 2D GRAPH PANEL SETUP ────────────────────────────────────────────────────
const svgNS = "http://www.w3.org/2000/svg";
const svg = document.createElementNS(svgNS, "svg");
svg.setAttribute("width", "100%");
svg.setAttribute("height", "100%");
svg.style.display = "block";
graphContainer.appendChild(svg);

function createSVGPath(color, strokeWidth = "2") {
    const path = document.createElementNS(svgNS, "path");
    path.setAttribute("fill", "none");
    path.setAttribute("stroke", color);
    path.setAttribute("stroke-width", strokeWidth);
    return path;
}
function createSVGText(text, color, bold = false, size = "11px") {
    const t = document.createElementNS(svgNS, "text");
    t.textContent = text;
    t.setAttribute("fill", color);
    t.setAttribute("font-family", "sans-serif");
    t.setAttribute("font-size", size);
    if (bold) t.setAttribute("font-weight", "bold");
    return t;
}

const fluxPath = createSVGPath("#0077cc");
const emfPath = createSVGPath("#e68a00");
svg.appendChild(fluxPath);
svg.appendChild(emfPath);

const axisLineY = createSVGPath("#000", "1");
const axisLineX1 = createSVGPath("#000", "1");
const axisLineX2 = createSVGPath("#000", "1");
svg.appendChild(axisLineY);
svg.appendChild(axisLineX1);
svg.appendChild(axisLineX2);

const markerLine = createSVGPath("#ff0000", "1.5");
markerLine.setAttribute("stroke-dasharray", "4,4");
svg.appendChild(markerLine);

const lblFlux = createSVGText("Magnetic Flux Φ = cos(θ)", "#0077cc", true);
const lblEMF = createSVGText("Induced EMF ε = sin(θ)", "#e68a00", true);
svg.appendChild(lblFlux);
svg.appendChild(lblEMF);

const labelsX = [];
const angles = [0, 90, 180, 270, 360];
for (let j = 0; j < 5; j++) {
    const t = createSVGText(angles[j] + "°", "#888", false, "10px");
    svg.appendChild(t);
    labelsX.push(t);
}

let graphInitialized = false;

function initGraphPaths() {
    if (graphInitialized) return;
    const rect = svg.getBoundingClientRect();
    if (rect.width === 0) return;

    const w = rect.width;
    const h = rect.height;
    const padX = 30;
    const padY = 20;
    const h1 = (h - padY * 2) / 2;

    const xStart = padX;
    const xEnd = w - 10;
    const graphW = xEnd - xStart;

    axisLineY.setAttribute("d", `M ${xStart},${padY - 5} L ${xStart},${h - padY + 15}`);

    const mid1 = padY + h1 / 2;
    const mid2 = padY + h1 + h1 / 2;

    axisLineX1.setAttribute("d", `M ${xStart},${mid1} L ${xEnd},${mid1}`);
    axisLineX2.setAttribute("d", `M ${xStart},${mid2} L ${xEnd},${mid2}`);

    lblFlux.setAttribute("x", xStart + 5);
    lblFlux.setAttribute("y", padY + 5);
    lblEMF.setAttribute("x", xStart + 5);
    lblEMF.setAttribute("y", padY + h1 + 5);

    for (let j = 0; j < 5; j++) {
        const lx = xStart + (angles[j] / 360) * graphW;
        labelsX[j].setAttribute("x", lx - 8);
        labelsX[j].setAttribute("y", mid2 + 15);
    }

    let dFlux = "", dEMF = "";
    const points = 80;
    const amp = h1 / 2 - 12;
    for(let i = 0; i <= points; i++) {
        const th_iter = (i / points) * Math.PI * 2;
        const x = xStart + (i / points) * graphW;

        const yF = mid1 - Math.cos(th_iter) * amp;
        dFlux += (i === 0 ? "M " : "L ") + `${x},${yF}`;

        const yE = mid2 - Math.sin(th_iter) * amp;
        dEMF += (i === 0 ? "M " : "L ") + `${x},${yE}`;
    }
    fluxPath.setAttribute("d", dFlux);
    emfPath.setAttribute("d", dEMF);

    graphInitialized = true;
}

function updateGraphMarker(theta) {
    if (graphContainer.style.display === 'none') return;
    if (!graphInitialized) initGraphPaths();

    const rect = svg.getBoundingClientRect();
    if (rect.width === 0) return;
    const padX = 30;
    const padY = 20;
    const xStart = padX;
    const graphW = rect.width - 10 - xStart;

    const normTheta = ((theta % 360) + 360) % 360;
    const curX = xStart + (normTheta / 360) * graphW;
    markerLine.setAttribute("d", `M ${curX},${padY - 5} L ${curX},${rect.height - padY + 15}`);
}

new ResizeObserver(() => {
    if (graphContainer.style.display !== 'none') {
        graphInitialized = false;
        updateGraphMarker(Number(coilAngleInput.value));
    }
}).observe(graphContainer);

// ─── 3D SCENE SETUP ──────────────────────────────────────────────────────────

const matSolid = new THREE.LineBasicMaterial({ color: 0x000000 });
const matDash = new THREE.LineDashedMaterial({ color: 0x000000, dashSize: 0.2, gapSize: 0.1 });

// Y axis (vertical, labeled z in diagram)
const yAxisBot = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, -5.5, 0), new THREE.Vector3(0, -3, 0)
]), matSolid);
const yAxisMid = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, -3, 0), new THREE.Vector3(0, 3, 0)
]), matDash);
yAxisMid.computeLineDistances();
const yArrowHelper = new THREE.ArrowHelper(new THREE.Vector3(0,1,0), new THREE.Vector3(0,3,0), 3, 0x000000, 0.4, 0.15);
scene.add(yAxisBot, yAxisMid, yArrowHelper);

// Z axis (diagonal projection, labeled x in diagram)
const zAxisBack = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(0, 0, -3), new THREE.Vector3(0, 0, 0)
]), matDash);
zAxisBack.computeLineDistances();
const zArrowHelper = new THREE.ArrowHelper(new THREE.Vector3(0,0,1), new THREE.Vector3(0,0,0), 5, 0x000000, 0.4, 0.15);
scene.add(zAxisBack, zArrowHelper);

// X axis (horizontal behind coil)
const xAxisLeft = new THREE.Line(new THREE.BufferGeometry().setFromPoints([
    new THREE.Vector3(-4, 0, 0), new THREE.Vector3(0, 0, 0)
]), matDash);
xAxisLeft.computeLineDistances();
scene.add(xAxisLeft);

// Rotation indicator arrow
const rotArcRadius = 0.8;
const rotArcPoints = [];
for (let i = 0; i <= 30; i++) {
    const a = -Math.PI * 0.2 + (i / 30) * Math.PI * 1.4;
    rotArcPoints.push(new THREE.Vector3(rotArcRadius * Math.cos(a), 4.7, rotArcRadius * Math.sin(a)));
}
const rotArcLine = new THREE.Line(new THREE.BufferGeometry().setFromPoints(rotArcPoints), matSolid);
scene.add(rotArcLine);

const endA = Math.PI * 1.2;
const rotDir = new THREE.Vector3(-Math.sin(endA), 0, Math.cos(endA)).normalize();
const endPt = rotArcPoints[rotArcPoints.length - 1];
const rotBackPt = new THREE.Vector3().copy(endPt).addScaledVector(rotDir, -0.1);
const rotHead = new THREE.ArrowHelper(rotDir, rotBackPt, 0.1, 0x000000, 0.3, 0.15);
scene.add(rotHead);

// Coil Geometry
const coilGroup = new THREE.Group();
scene.add(coilGroup);

const coilMat = new THREE.LineBasicMaterial({ color: 0x888888, linewidth: 2 });
for (let i = 0; i < 4; i++) {
    const xOffset = -0.15 + i * 0.1;
    const pts = [
        new THREE.Vector3(xOffset, 3, 2),
        new THREE.Vector3(xOffset, 3, -2),
        new THREE.Vector3(xOffset, -3, -2),
        new THREE.Vector3(xOffset, -3, 2),
        new THREE.Vector3(xOffset, 3, 2)
    ];
    coilGroup.add(new THREE.Line(new THREE.BufferGeometry().setFromPoints(pts), coilMat));
}

// Bold Vector Helper
function createBoldArrow(dir, origin, length, color) {
    const group = new THREE.Group();
    const cylLen = length - 0.4;
    const cylGeom = new THREE.CylinderGeometry(0.06, 0.06, cylLen, 8);
    cylGeom.translate(0, cylLen / 2, 0);
    const mat = new THREE.MeshBasicMaterial({ color: color });
    group.add(new THREE.Mesh(cylGeom, mat));

    const coneGeom = new THREE.ConeGeometry(0.18, 0.5, 12);
    coneGeom.translate(0, length - 0.25, 0);
    group.add(new THREE.Mesh(coneGeom, mat));

    const q = new THREE.Quaternion().setFromUnitVectors(new THREE.Vector3(0, 1, 0), dir.clone().normalize());
    group.quaternion.copy(q);
    group.position.copy(origin);
    return group;
}

// Fixed B Field Vector
const bArrow = createBoldArrow(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 4.5, 0x0077cc);
scene.add(bArrow);

// Rotating Normal Vector
const nArrow = createBoldArrow(new THREE.Vector3(1, 0, 0), new THREE.Vector3(0, 0, 0), 3, 0xe68a00);
coilGroup.add(nArrow);

// Theta Angle Arc
const thetaArcLine = new THREE.Line(new THREE.BufferGeometry(), matSolid);
scene.add(thetaArcLine);
const thetaArrow = new THREE.ArrowHelper(new THREE.Vector3(0,0,1), new THREE.Vector3(), 0.1, 0x000000, 0.25, 0.15);
scene.add(thetaArrow);

// Labels
const lbl_z = addLabel('<i>z</i>', new THREE.Vector3(0, 6.4, 0), { fontSize: '15px' });
const lbl_x = addLabel('<i>x</i>', new THREE.Vector3(0, 0, 5.4), { fontSize: '15px' });
const lbl_B = addLabel('<b>B</b>', new THREE.Vector3(4.8, -0.3, 0), { color: '#0077cc', fontSize: '16px' });
const lbl_n = addLabel('<b>n̂</b>', new THREE.Vector3(0, 0, 0), { color: '#e68a00', fontSize: '16px' });
const lbl_theta = addLabel('<i>θ</i>', new THREE.Vector3(0, 0, 0), { fontSize: '15px' });

// Interactive tooltips
registerInteractive(rotArcLine, {
    title: "Rotation",
    body: "The coil rotates around the vertical z-axis at a constant angular velocity."
});
registerInteractive(bArrow, {
    title: "Magnetic Field (B)",
    tooltip: "Uniform external magnetic field",
    body: "A uniform external magnetic field points steadily to the right."
});
registerInteractive(nArrow, {
    title: "Area Normal (n̂)",
    tooltip: "Perpendicular vector to the coil face",
    body: "This vector is perpendicular to the coil's face. As the coil rotates, the angle θ between n̂ and B changes, varying the magnetic flux."
});
registerInteractive(coilGroup, {
    title: "Coil",
    tooltip: "Rectangular wire coil",
    body: "A rectangular loop of wire. The changing magnetic flux induces an EMF (voltage) in the coil."
});

// ─── STATE & ANIMATION ───────────────────────────────────────────────────────
let isPlaying = false;
const clock = new THREE.Clock();

function updateScene() {
    let th = Number(coilAngleInput.value);
    const rad = th * Math.PI / 180;

    // Rotate coil (n-hat sweeps from +X toward +Z, mapped to -Y rotation)
    coilGroup.rotation.y = -rad;
    coilGroup.updateMatrixWorld(true);

    // Position n-hat label near tip
    const nTipLocal = new THREE.Vector3(3.3, -0.3, 0);
    const nTipWorld = nTipLocal.clone().applyMatrix4(coilGroup.matrixWorld);
    lbl_n.pos.copy(nTipWorld);

    // Draw theta arc in world space
    const normRad = ((rad % (Math.PI * 2)) + Math.PI * 2) % (Math.PI * 2);
    if (normRad < 0.05 || normRad > Math.PI * 2 - 0.05) {
        thetaArcLine.visible = false;
        thetaArrow.visible = false;
        lbl_theta.div.style.display = 'none';
    } else {
        thetaArcLine.visible = true;
        thetaArrow.visible = true;
        lbl_theta.div.style.display = '';

        const arcPts = [];
        const r = 1.5;
        const steps = Math.max(5, Math.floor((normRad / Math.PI) * 20));
        for (let i = 0; i <= steps; i++) {
            const a = (i / steps) * normRad;
            arcPts.push(new THREE.Vector3(r * Math.cos(a), 0, r * Math.sin(a)));
        }
        thetaArcLine.geometry.dispose();
        thetaArcLine.geometry = new THREE.BufferGeometry().setFromPoints(arcPts);

        const tang = new THREE.Vector3(-Math.sin(normRad), 0, Math.cos(normRad)).normalize();
        const lastPt = arcPts[arcPts.length - 1];
        const backPt = new THREE.Vector3().copy(lastPt).addScaledVector(tang, -0.1);
        thetaArrow.position.copy(backPt);
        thetaArrow.setDirection(tang);

        const halfA = normRad / 2;
        lbl_theta.pos.set((r + 0.3) * Math.cos(halfA), 0, (r + 0.3) * Math.sin(halfA));
    }

    if (showGraphsToggle.checked) {
        updateGraphMarker(th);
    }
}

playRotationBtn.addEventListener('click', () => {
    isPlaying = !isPlaying;
    playRotationBtn.textContent = isPlaying ? 'Stop Rotation' : 'Play Rotation';
    playRotationBtn.classList.toggle('active', isPlaying);
    if (isPlaying) clock.getDelta();
});

coilAngleInput.addEventListener('input', () => {
    if (isPlaying) {
        isPlaying = false;
        playRotationBtn.textContent = 'Play Rotation';
        playRotationBtn.classList.remove('active');
    }
    updateScene();
});

showGraphsToggle.addEventListener('change', () => {
    graphContainer.style.display = showGraphsToggle.checked ? 'block' : 'none';
    if (showGraphsToggle.checked) {
        document.body.style.setProperty('--ui-size', `380px`);
        updateGraphMarker(Number(coilAngleInput.value));
    } else {
        document.body.style.setProperty('--ui-size', `300px`);
    }
    window.dispatchEvent(new Event('resize'));
});

function tickAnimation() {
    requestAnimationFrame(tickAnimation);
    if (isPlaying) {
        let th = Number(coilAngleInput.value);
        th += 60 * clock.getDelta(); // 60 deg/sec
        if (th >= 360) th -= 360;
        coilAngleInput.value = th;
        updateScene();
    }
}
tickAnimation();

// Standard oblique projection aligns +X right, +Y up, and shears +Z to front-left.
setCameraView({ 
    projection: 'oblique', 
    obliqueAngleDeg: 45, 
    depthScale: 0.5 
});

updateScene();
// @FIGURE_CODE_END

